    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0d1117;
        --panel: #161b22;
        --panel-strong: #1f2630;
        --text: #f0f6fc;
        --muted: #9da7b3;
        --accent: #7c3aed;
        --accent-bright: #a78bfa;
        --danger: #ff7b72;
        --success: #3fb950;
        --border: #30363d;
        --focus: #58a6ff;
      }

