        --bg: #0d1117;
        --panel: #161b22;
        --panel-strong: #1f2630;
        --text: #f0f6fc;
        --muted: #9da7b3;
        --accent: #7c3aed;
        --accent-bright: #a78bfa;
        --danger: #ff7b72;
        --success: #3fb950;
        --border: #30363d;
        --focus: #58a6ff;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 1.5rem;
        background:
          radial-gradient(circle at top left, rgba(124, 58, 237, 0.25), transparent 34rem),
          radial-gradient(circle at bottom right, rgba(88, 166, 255, 0.16), transparent 30rem),
          var(--bg);
        color: var(--text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      a {
        color: var(--accent-bright);
      }

      a:hover {
        color: #c4b5fd;
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 1;
        transform: translateY(-150%);
        padding: 0.65rem 0.9rem;
        border-radius: 999px;
        background: var(--text);
        color: var(--bg);
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        width: min(100%, 34rem);
      }

      .card {
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-radius: 1.5rem;
        background: linear-gradient(145deg, rgba(22, 27, 34, 0.94), rgba(13, 17, 23, 0.96));
        box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.45);
      }

      .card__header {
        padding: 2rem 2rem 1rem;
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent-bright);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 8vw, 2.45rem);
        line-height: 1.1;
      }

      .intro,
      .required-note,
      .helper-text {
        color: var(--muted);
      }

      .intro {
        margin: 0.85rem 0 0;
      }

      form {
        display: grid;
        gap: 1.25rem;
        padding: 1.5rem 2rem 2rem;
      }

      .required-note {
        margin: 0;
        font-size: 0.9rem;
      }

      .form-field {
        display: grid;
        gap: 0.65rem;
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: rgba(31, 38, 48, 0.74);
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.75rem;
        align-items: start;
      }

      input[type="checkbox"] {
        width: 1.35rem;
        height: 1.35rem;
        margin: 0.15rem 0 0;
        accent-color: var(--accent);
        cursor: pointer;
      }

      label {
        color: var(--text);
        font-weight: 700;
      }

      .required-marker {
        color: var(--danger);
        font-weight: 800;
      }

      .helper-text,
      .error-text,
      .status-text {
        margin: 0;
        font-size: 0.95rem;
      }

      .error-text {
        color: var(--danger);
        font-weight: 700;
      }

      .status-text {
        min-height: 1.5rem;
        color: var(--success);
        font-weight: 700;
      }

      [hidden] {
        display: none !important;
      }

      button {
        min-height: 3rem;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent), #2563eb);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        box-shadow: 0 1rem 2rem rgba(37, 99, 235, 0.25);
      }

      button:hover {
        background: linear-gradient(135deg, #8b5cf6, #3b82f6);
      }

      @media (max-width: 26rem) {
        body {
          padding: 1rem;
        }

        .card__header,
        form {
          padding-left: 1.25rem;
          padding-right: 1.25rem;
        }
      }

      @media (prefers-reduced-motion: no-preference) {
        a,
        button,
        .skip-link {
          transition: background 160ms ease, color 160ms ease, transform 160ms ease;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
