          background: ButtonFace;
          color: ButtonText;
          box-shadow: none;
        }

        .required-marker,
        .error-text {
          color: Mark;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main" tabindex="-1"></main>

    <script>
      const ConsentCheckbox = () => `
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="terms-consent"
              name="terms-consent"
              type="checkbox"
              required
              aria-describedby="terms-help terms-error"
            >
            <label for="terms-consent">
              I agree to the <a href="#terms">Terms of Use</a>
              <span class="required-marker" aria-hidden="true">*</span>
            </label>
          </div>
          <p id="terms-help" class="helper-text">Required to create and manage your account.</p>
          <p id="terms-error" class="error-text" hidden>Error: You must agree to the terms before submitting.</p>
        </div>
      `;

      const SubmitButton = () => `
        <button type="submit">Agree and continue</button>
      `;

      const ConsentForm = () => `
        <section class="card" aria-labelledby="form-title">
          <div class="card__header">
            <p class="eyebrow">Consent required</p>
            <h1 id="form-title">Review the terms</h1>
            <p class="intro">Confirm your agreement before continuing.</p>
          </div>
          <form id="consent-form" novalidate>
            <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> indicates a required field.</p>
            ${ConsentCheckbox()}
            ${SubmitButton()}
            <p id="form-status" class="status-text" aria-live="polite"></p>
          </form>
        </section>
      `;

      const App = () => ConsentForm();

      document.querySelector("#main").innerHTML = App();

      const form = document.querySelector("#consent-form");
      const checkbox = document.querySelector("#terms-consent");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      const setConsentError = (showError) => {
        checkbox.setAttribute("aria-invalid", String(showError));
        error.hidden = !showError;
      };

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          setConsentError(false);
          status.textContent = "";
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          setConsentError(true);
          status.textContent = "";
          checkbox.focus();
          return;
        }

        setConsentError(false);
        status.textContent = "Thanks. Your consent has been recorded.";
      });
    </script>
  </body>
</html>
